    required this.rows,
    required this.totalAmountSat,
    required this.totalFeeSat,
    required this.droppedUtxoCount,
  });

  @override
  int get hashCode =>
      planId.hashCode ^
      tipHeight.hashCode ^
      rows.hashCode ^
      totalAmountSat.hashCode ^
      totalFeeSat.hashCode ^
      droppedUtxoCount.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is APISpacedPlanSummary &&
          runtimeType == other.runtimeType &&
          planId == other.planId &&
          tipHeight == other.tipHeight &&
          rows == other.rows &&
          totalAmountSat == other.totalAmountSat &&
          totalFeeSat == other.totalFeeSat &&
          droppedUtxoCount == other.droppedUtxoCount;
}

class APISpendPath {
  final int id;
  final List<APIPolicyPath> policyPath;
  final int threshold;
  final List<String> mfps;
  final APIRelativeTimelock relTimelock;
  final APIAbsoluteTimelock absTimelock;
  final int wuBase;
  final int wuIn;
  final int wuOut;
  final int trDepth;

  /// Per-MFP multipath lanes (every chain index this key contributes in this
  /// spend path). For canonical `<0;1>/*` this is `[0, 1]`; for non-canonical
  /// pairs like `<8;9>/*` it is `[8, 9]`. HW signing uses the full set to
  /// recognise UTXOs derived via either lane (e.g. change UTXOs whose path
  /// ends in the second component of the pair).
  final Map<String, Uint32List> keyChanges;
  final double vbSweep;

  const APISpendPath({
    required this.id,
    required this.policyPath,
    required this.threshold,
    required this.mfps,
    required this.relTimelock,
    required this.absTimelock,
    required this.wuBase,
    required this.wuIn,
    required this.wuOut,
    required this.trDepth,
    required this.keyChanges,
    required this.vbSweep,
  });

  static Future<List<APISpendPath>> fromSorted({
    required List<SpendPath> coreSpendPaths,
  }) => RustLib.instance.api.crateApiModelApiSpendPathFromSorted(
    coreSpendPaths: coreSpendPaths,
  );

  @override
  int get hashCode =>
      id.hashCode ^
      policyPath.hashCode ^
      threshold.hashCode ^
      mfps.hashCode ^
      relTimelock.hashCode ^
      absTimelock.hashCode ^
      wuBase.hashCode ^
      wuIn.hashCode ^
      wuOut.hashCode ^
      trDepth.hashCode ^
      keyChanges.hashCode ^
      vbSweep.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is APISpendPath &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          policyPath == other.policyPath &&
          threshold == other.threshold &&
          mfps == other.mfps &&
          relTimelock == other.relTimelock &&
          absTimelock == other.absTimelock &&
          wuBase == other.wuBase &&
          wuIn == other.wuIn &&
          wuOut == other.wuOut &&
          trDepth == other.trDepth &&
          keyChanges == other.keyChanges &&
          vbSweep == other.vbSweep;
}

