/// Preview of an unsigned transaction before persisting a PSBT.
///
/// All amounts are in sats. `fee_rate_sat_per_vb` is the back-computed effective rate
/// even when the caller passed an absolute fee. `total_wu` is BDK's actual weight for the
/// resulting tx (drain or change present). `has_change` is true when a change output was added.
///
/// `insufficient_funds` is set instead of returning an error so the UI can render
/// gracefully while the user is still typing. Other fields hold sentinel zeros in that case.
///
/// `recipients` contains the canonical-encoded recipient addresses (parsed by BDK) and the
/// final amounts — for the drain recipient the amount reflects what BDK actually assigned.
///
/// `rbf_min_fee_sats` is the minimum absolute fee (BIP-125 Rule 4 / PaysForRBF) that the
/// replacement tx must strictly exceed, computed from the conflict cluster and the actual
/// new tx vsize. None when no RBF conflicts were declared.
class APITxPreview {
  final BigInt feeSats;
  final double feeRateSatPerVb;
  final BigInt changeSats;
  final BigInt sendSats;
  final BigInt totalWu;
  final bool hasChange;
  final bool insufficientFunds;
  final List<APIRecipient> recipients;
  final BigInt? rbfMinFeeSats;

  const APITxPreview({
    required this.feeSats,
    required this.feeRateSatPerVb,
    required this.changeSats,
    required this.sendSats,
    required this.totalWu,
    required this.hasChange,
    required this.insufficientFunds,
    required this.recipients,
    this.rbfMinFeeSats,
  });

  @override
  int get hashCode =>
      feeSats.hashCode ^
      feeRateSatPerVb.hashCode ^
      changeSats.hashCode ^
      sendSats.hashCode ^
      totalWu.hashCode ^
      hasChange.hashCode ^
      insufficientFunds.hashCode ^
      recipients.hashCode ^
      rbfMinFeeSats.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is APITxPreview &&
          runtimeType == other.runtimeType &&
          feeSats == other.feeSats &&
          feeRateSatPerVb == other.feeRateSatPerVb &&
          changeSats == other.changeSats &&
          sendSats == other.sendSats &&
          totalWu == other.totalWu &&
          hasChange == other.hasChange &&
          insufficientFunds == other.insufficientFunds &&
          recipients == other.recipients &&
          rbfMinFeeSats == other.rbfMinFeeSats;
}

class APIUtxo {
  final String txid;
  final int vout;
  final BigInt valueSat;
  final APIKeychain keychain;
  final int derivationIndex;
  final String address;
  final bool isConfirmed;
  final int? confirmationHeight;

  /// Unix timestamp of the block that confirmed this UTXO; None = unconfirmed.
  final BigInt? confirmationTime;

  /// Explicit user-set label (use for editing).
  final String? label;

  /// Display label — own label if set, otherwise inherited from a related entity.
  final String? effectiveLabel;

  /// True when `effective_label` is auto-propagated from a related entity, not explicitly set.
  final bool isAuto;

  /// IDs of pending PSBTs (unsigned_txs.id) that spend this UTXO.
  /// Empty for most coins; populated by get_utxos().
  final Int64List pendingPsbtIds;

  /// TXID of an unconfirmed (mempool) transaction that spends this UTXO, if any.
  /// Higher-priority indicator than pending_psbt_ids: the spend has already been broadcast.
  final String? mempoolSpendingTxid;

  const APIUtxo({
    required this.txid,
    required this.vout,
    required this.valueSat,
    required this.keychain,
    required this.derivationIndex,
    required this.address,
    required this.isConfirmed,
    this.confirmationHeight,
    this.confirmationTime,
    this.label,
    this.effectiveLabel,
    required this.isAuto,
    required this.pendingPsbtIds,
    this.mempoolSpendingTxid,
  });

  @override
  int get hashCode =>
      txid.hashCode ^
      vout.hashCode ^
      valueSat.hashCode ^
      keychain.hashCode ^
      derivationIndex.hashCode ^
      address.hashCode ^
      isConfirmed.hashCode ^
      confirmationHeight.hashCode ^
      confirmationTime.hashCode ^
      label.hashCode ^
      effectiveLabel.hashCode ^
      isAuto.hashCode ^
      pendingPsbtIds.hashCode ^
      mempoolSpendingTxid.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is APIUtxo &&
          runtimeType == other.runtimeType &&
          txid == other.txid &&
          vout == other.vout &&
          valueSat == other.valueSat &&
          keychain == other.keychain &&
          derivationIndex == other.derivationIndex &&
          address == other.address &&
          isConfirmed == other.isConfirmed &&
          confirmationHeight == other.confirmationHeight &&
          confirmationTime == other.confirmationTime &&
          label == other.label &&
          effectiveLabel == other.effectiveLabel &&
          isAuto == other.isAuto &&
          pendingPsbtIds == other.pendingPsbtIds &&
          mempoolSpendingTxid == other.mempoolSpendingTxid;
}

